#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

int main() {
  std::string filename;
  std::string word;

  std::cout << "Enter filename: ";
  std::cin >> filename;

  std::cout << "Enter word to search for: ";
  std::cin >> word;

  std::ifstream inputFile(filename);
  if (!inputFile.is_open()) {
    std::cerr << "Error opening file." << std::endl;
    return 1;
  }

  int count = 0;
  std::string line;
  while (std::getline(inputFile, line)) {
    std::stringstream ss(line);
    std::string temp;
    while (ss >> temp) {
      if (temp == word) {
        count++;
      }
    }
  }

  inputFile.close();
  std::cout << "The word '" << word << "' appears " << count << " times in the file." << std::endl;

  return 0;
}
